    [Export] public int num = 1;
    [Export] public byte[] arr = [1, 2, 3, 4, 5, 6, 7, 8];
    [Export] public string string_ = "string";
    [Export] public Node2D node = new();
    [Export] public RefCounted refCounted = new();


