    [Benchmark]
    public void CreateByteArray_Base()
    {
        for (int i = 0; i < Count; i++)
        {
            var variant = Variant.CreateFrom(arr);
        }
    }

    [Benchmark]
    public void CreateByteArray_Pool()
    {
        for (int i = 0; i < Count; i++)
        {
            using var variant = Variant.CreateFrom(arr);
        }
    }

    [Benchmark]
    public void CreateString_Base()
    {
        for (int i = 0; i < Count; i++)
        {
            var variant = Variant.CreateFrom(string_);
        }
    }

    [Benchmark]
    public void CreateString_Pool()
    {
        for (int i = 0; i < Count; i++)
        {
            using var variant = Variant.CreateFrom(string_);
        }
    }

    [Benchmark]
    public void CreateRefCounted_Base()
    {
        for (int i = 0; i < Count; i++)
        {
            var variant = Variant.CreateFrom(refCounted);
        }
    }

    [Benchmark]
    public void CreateRefCounted_Pool()
    {
        for (int i = 0; i < Count; i++)
        {
            using var variant = Variant.CreateFrom(refCounted);
        }
    }

    [Benchmark]
    public void CreateNode2D_Base()
    {
        for (int i = 0; i < Count; i++)
        {
            var variant = Variant.CreateFrom(node);
        }
    }

    [Benchmark]
    public void CreateNode2D_Pool()
    {
        for (int i = 0; i < Count; i++)
        {
            using var variant = Variant.CreateFrom(node);
        }
    }
}

